# Generated by Descant: acceptance tests.

# frozen_string_literal: true

require "rails_helper"
require "webmock/rspec"

RSpec.describe "Reservation route access" do
  include_context "timekeeping entry writes"
  include_context "timekeeping entry writes without transactional fixtures"

  it "refuses user tokens, services without the operation and other companies' services on every reservation route and writes nothing" do
    company = timekeeping_arrange.company
    other_company = timekeeping_arrange.company
    routes = %w[prepare commit abort mark_billed detach_entries]
    employee = timekeeping_arrange.user(company:, role: "employee")
    project = timekeeping_arrange.project(company:)
    entry_id = timekeeping_arrange.entry(company:, user: employee, project:)
    billable = timekeeping_arrange.reserved_entry(company:, invoice_id: 501, state: "committed")
    agent_entry = timekeeping_arrange.entry(company:, user: employee, project:, agent_id: 77)
    owner_token = timekeeping_arrange.token_for(timekeeping_arrange.user(company:, role: "owner"))
    without_operations = timekeeping_arrange.service_identity(company:, name: "reporting", operations: [])
    other_company_service = timekeeping_arrange.service_identity(company: other_company, name: "invoice-boundary",
                                                                  operations: routes)
    paths = {
      "prepare" => "/v1/companies/#{company}/reservations/prepare",
      "commit" => "/v1/companies/#{company}/reservations/commit",
      "abort" => "/v1/companies/#{company}/reservations/abort",
      "mark_billed" => "/v1/companies/#{company}/invoices/501/mark-billed",
      "detach_entries" => "/v1/companies/#{company}/agents/77/detach-entries"
    }
    baseline = { entries: Entry.order(:id).pluck(:id, :bill_status, :agent_id, :version), reservations: Reservation.count,
                 audit: AuditEvent.count, outbox: OutboxSnapshot.count }
    expect(baseline[:entries].pluck(2)).to include(77)

    # "An anonymous or user-delegated request never gets it."
    expected = { nil => [401, "unauthorized"], owner_token => [403, "forbidden"],
                 without_operations => [403, "forbidden"], other_company_service => [404, "not_found"] }
    paths.each do |route, path|
      expected.each do |credential, (status, reason)|
        headers = { "Content-Type" => "application/json" }
        headers["Authorization"] = "Bearer #{credential}" if credential
        body = { "invoice_id" => 501, "operation_id" => SecureRandom.uuid, "generation" => timekeeping_arrange.current_generation,
                 "disposition" => "active", "entries" => [entry_id, billable] }
        post path, params: JSON.generate(body), headers: headers

        expect([route, response.status, response.parsed_body]).to eq([route, status, { "reason" => reason }])
      end
    end
    expect(entry_id).to be_positive
    expect(agent_entry).to be_positive
    expect({ entries: Entry.order(:id).pluck(:id, :bill_status, :agent_id, :version), reservations: Reservation.count,
             audit: AuditEvent.count, outbox: OutboxSnapshot.count }).to eq(baseline)
  end
end
